229	
230	export default function KanbanBoard({
231	  candidates,
232	  onStageChange,
233	  stages,
234	  stageConfig: customStageConfig,
235	}: KanbanBoardProps) {
236	  // Build a merged resolver: custom config → STAGE_CONFIG fallback
237	  const resolveStageConfig = (stage: string) => {
238	    if (customStageConfig && customStageConfig[stage]) {
239	      const custom = customStageConfig[stage];
240	      return {
241	        label: custom.label,
242	        header: "bg-muted text-foreground",
243	        card: "border-border",
244	        badge: "bg-muted text-foreground",
245	      };
246	    }
247	    return getStageConfig(stage);
248	  };
249	  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);
250	  const [draggingId, setDraggingId] = useState<string | null>(null);
251	
252	  const handleDragStart = useCallback(
253	    (e: React.DragEvent, candidateId: string) => {
254	      setDraggingId(candidateId);
255	      e.dataTransfer.effectAllowed = "move";
256	      e.dataTransfer.setData("candidateId", candidateId);
257	    },
258	    []
259	  );
260	
261	  const handleDragOver = useCallback(
262	    (e: React.DragEvent, stage: string) => {
263	      e.preventDefault();
264	      e.dataTransfer.dropEffect = "move";
265	      setDragOverColumn(stage);
266	    },
267	    []
268	  );
269	
270	  const handleDragLeave = useCallback(() => {
271	    setDragOverColumn(null);
272	  }, []);
273	
274	  const handleDrop = useCallback(
275	    (e: React.DragEvent, targetStage: string) => {
276	      e.preventDefault();
277	      setDragOverColumn(null);
278	      const candidateId = e.dataTransfer.getData("candidateId");
279	      if (!candidateId) return;
280	
281	      const candidate = candidates.find((c) => c.id === candidateId);
282	      if (!candidate) return;
283	      if (candidate.stage === targetStage) return;
284	
285	      onStageChange(candidateId, targetStage);
286	      setDraggingId(null);
287	    },
288	    [candidates, onStageChange]
289	  );
290	
291	  // Group candidates by stage
292	  const grouped = stages.reduce<Record<string, KanbanCandidate[]>>(
293	    (acc, stage) => {
294	      acc[stage] = candidates.filter((c) => c.stage === stage);
295	      return acc;
296	    },
297	    {}
298	  );
299	
300	  // Candidates whose stage doesn't match any known column fall into "applied"
301	  const knownStages = new Set(stages);
302	  candidates.forEach((c) => {
303	    if (!knownStages.has(c.stage)) {
304	      grouped["applied"] = [...(grouped["applied"] ?? []), c];
305	    }
306	  });
307	
308	  return (
309	    <div
310	      className="overflow-x-auto pb-4"
311	      onDragEnd={() => {
312	        setDragOverColumn(null);
313	        setDraggingId(null);
314	      }}
315	    >
316	      <div className="flex gap-3 min-w-max">
317	        {stages.map((stage) => (
318	          <KanbanColumn
319	            key={stage}
320	            stage={stage}
321	            stages={stages}
322	            candidates={grouped[stage] ?? []}
323	            onDragStart={handleDragStart}
324	            onDragOver={handleDragOver}
325	            onDragLeave={handleDragLeave}
326	            onDrop={handleDrop}
327	            onStageChange={onStageChange}
328	            isDragOver={dragOverColumn === stage && draggingId !== null}
329	            resolveConfig={customStageConfig ? resolveStageConfig : undefined}
330	          />
331	        ))}
332	      </div>
333	    </div>
334	  );
335	}
